class Stack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        return self.stack.pop()

    def is_empty(self):
        return len(self.stack) == 0


class Queue:
    def __init__(self):
        self.stack1 = Stack()
        self.stack2 = Stack()

